code=list(D.glob('*.py'))+[B/n for n in ['scan_mesh_motion.py','mesh_collision.py','kinematics_numpy.py']]+[P/n for n in ['verify_audit_evidence.py','write_audit_index.py','background_tasks.pyw']]
